package gpu

import (
	"bytes"
	"fmt"
	"strconv"

	"sigs.k8s.io/yaml"

	"github.com/hermeto/aibox/internal/profile"
)

// Header is written at the top of generated files.
const Header = "# Generated by `aibox render nodepools` from profiles/%s.yaml — do not edit.\n# Regenerate with `make generate`; CI fails on drift.\n"

// Render returns the EC2NodeClasses and NodePools for every GPU class of a cloud profile.
func Render(p *profile.Profile) ([]byte, error) {
	if p.Spec.AWS == nil {
		return nil, fmt.Errorf("profile %s has no GPU classes (not an AWS profile)", p.Metadata.Name)
	}
	var out bytes.Buffer
	fmt.Fprintf(&out, Header, p.Metadata.Name)
	cluster := p.Spec.Cluster.Name
	for _, c := range p.Spec.AWS.GPUClasses {
		largest := InstanceSpec{}
		for _, t := range c.InstanceTypes {
			spec, ok := Instances[t]
			if !ok {
				return nil, fmt.Errorf("gpu class %s: unknown instance type %s (add it to internal/gpu/instances.go)", c.Name, t)
			}
			if spec.GPUs > largest.GPUs || (spec.GPUs == largest.GPUs && spec.VCPUs > largest.VCPUs) {
				largest = spec
			}
		}
		for _, obj := range []any{nodeClass(cluster, p.Metadata.Name, c), nodePool(c, largest)} {
			b, err := yaml.Marshal(obj)
			if err != nil {
				return nil, err
			}
			out.WriteString("---\n")
			out.Write(b)
		}
	}
	return out.Bytes(), nil
}

func nodeClass(cluster, profileName string, c profile.GPUClass) map[string]any {
	spec := map[string]any{
		"amiSelectorTerms":           []any{map[string]any{"alias": AMIAlias}},
		"role":                       cluster + "-karpenter-node",
		"subnetSelectorTerms":        []any{map[string]any{"tags": map[string]any{"karpenter.sh/discovery": cluster}}},
		"securityGroupSelectorTerms": []any{map[string]any{"tags": map[string]any{"karpenter.sh/discovery": cluster}}},
		"instanceStorePolicy":        "RAID0",
		"metadataOptions": map[string]any{
			"httpEndpoint": "enabled", "httpTokens": "required", "httpPutResponseHopLimit": 1,
		},
		// run-id is added per run by the app-of-apps (kustomize patch) for orphan detection.
		"tags": map[string]any{"project": "aibox", "profile": profileName, "aibox.dev/gpu-class": c.Name},
	}
	if c.CapacityType == profile.CapacityCapacityBlock {
		spec["capacityReservationSelectorTerms"] = []any{map[string]any{"id": c.CapacityReservationID}}
	}
	return map[string]any{
		"apiVersion": "karpenter.k8s.aws/v1",
		"kind":       "EC2NodeClass",
		"metadata":   map[string]any{"name": "aibox-" + c.Name, "labels": map[string]any{"app.kubernetes.io/part-of": "aibox"}},
		"spec":       spec,
	}
}

func nodePool(c profile.GPUClass, largest InstanceSpec) map[string]any {
	capacity := c.CapacityType
	if capacity == profile.CapacityCapacityBlock {
		capacity = "reserved"
	}
	return map[string]any{
		"apiVersion": "karpenter.sh/v1",
		"kind":       "NodePool",
		"metadata":   map[string]any{"name": c.Name, "labels": map[string]any{"app.kubernetes.io/part-of": "aibox"}},
		"spec": map[string]any{
			"template": map[string]any{
				"metadata": map[string]any{"labels": map[string]any{ClassLabel: c.Name}},
				"spec": map[string]any{
					"nodeClassRef": map[string]any{"group": "karpenter.k8s.aws", "kind": "EC2NodeClass", "name": "aibox-" + c.Name},
					"taints":       []any{map[string]any{"key": GPUTaintKey, "value": GPUTaintValue, "effect": "NoSchedule"}},
					"requirements": []any{
						map[string]any{"key": "node.kubernetes.io/instance-type", "operator": "In", "values": c.InstanceTypes},
						map[string]any{"key": "karpenter.sh/capacity-type", "operator": "In", "values": []string{capacity}},
						map[string]any{"key": "kubernetes.io/arch", "operator": "In", "values": []string{"amd64"}},
					},
					"expireAfter": ExpireAfter,
				},
			},
			"disruption": map[string]any{"consolidationPolicy": "WhenEmpty", "consolidateAfter": DefaultConsolidateAfter},
			"limits": map[string]any{
				"cpu":            strconv.Itoa(c.MaxNodes * largest.VCPUs),
				"nvidia.com/gpu": strconv.Itoa(c.MaxNodes * largest.GPUs),
			},
		},
	}
}
